/*
 * index.js — GENERATED wiring for the schema-renderer split.
 *
 * Assembles the public window.SchemaRenderer API from all extracted modules,
 * wraps every render in safeRender() for error tracking, and exposes an
 * inspectable error log.
 *
 * Load order (see load-order.txt): helpers → heading → figure-utils →
 * chart-cache → renderers/* → product/* → chart-mount → render-section →
 * THIS FILE (index.js) last.
 *
 * Generated by A-renderer.extract.py. Review before cutover.
 */
((AGF) => {
	// ── Central error log (inspectable via SchemaRenderer.errorLog) ──────
	var errorLog = [];
	function logError(scope, err, extra) {
		var entry = {
			ts: Date.now(),
			scope: scope,
			message: (err && err.message) || String(err),
			error: err,
			data: extra || null,
		};
		errorLog.push(entry);
		try {
			console.error("[agf:" + scope + "]", err);
		} catch (_) {}
		return entry;
	}

	// ── safeRender: wrap every renderer dispatch in try/catch ───────────
	function safeRender(fn, section) {
		var schemaId = section && section.schema_id;
		if (typeof fn !== "function") {
			logError(
				"render:" + schemaId,
				new Error('No renderer registered for schema_id "' + schemaId + '"'),
			);
			return (
				'<section class="render-error" data-schema="' +
				(AGF.helpers && AGF.helpers.esc
					? AGF.helpers.esc(schemaId)
					: schemaId) +
				'"><p>\u26A0 No renderer for "' +
				schemaId +
				'".</p></section>'
			);
		}
		try {
			return fn(section);
		} catch (err) {
			logError("render:" + schemaId, err, { schema_id: schemaId });
			var safe =
				AGF.helpers && AGF.helpers.esc ? AGF.helpers.esc(schemaId) : schemaId;
			return (
				'<section class="render-error" data-schema="' +
				safe +
				'"><p>\u26A0 Section "' +
				safe +
				'" failed to render. See console / SchemaRenderer.errorLog.</p></section>'
			);
		}
	}

	// ── Routed render that mirrors the original renderSection contract ──
	// The original renderSection() does more (figure/text injection, bg,
	// appendix). It lives verbatim in render-section.js. Here we only add
	// an error-tracked entry point that delegates to it.
	function renderSectionTracked(section) {
		try {
			return AGF.renderSection(section);
		} catch (err) {
			logError("renderSection", err, {
				schema_id: section && section.schema_id,
			});
			return '<section class="render-error"><p>\u26A0 renderSection failed. See console.</p></section>';
		}
	}

	// ── Public API (mirrors original src lines 1456–1465) ───────────────
	var H = AGF.helpers || {};
	var P = AGF.product || {};
	globalThis.SchemaRenderer = {
		renderSection: renderSectionTracked,
		renderProductsBlock: P.renderProductsBlock,
		hydrateProductVisualizations: P.hydrateProductVisualizations,
		renderers: AGF.REGISTRY || AGF.renderers || {},
		helpers: {
			esc: H.esc,
			md: H.md,
			fmtUSD: H.fmtUSD,
			fmtRange: H.fmtRange,
			splitHeadline: H.splitHeadline,
			toRoman: H.toRoman,
		},
		mountCharts: AGF.mountCharts,
		renderHeader: (AGF.renderers || {}).header,
		renderFooter: (AGF.renderers || {}).footer,
		renderOverview: (AGF.renderers || {}).overview,
		renderConceptExplainer: (AGF.renderers || {})["concept-explainer"],
		// ── error-tracking surface (new) ──
		errorLog: errorLog,
		flushErrors: () => {
			var n = errorLog.length;
			errorLog.length = 0;
			return n;
		},
		_safeRender: safeRender, // exposed for testing
	};

	// ── Shared error surface across feature-folders (app/editor/renderer) ──
	// Per-module load failures push here; safeRender failures push to errorLog.
	// Mirror so a single `AGF._errors` inspection catches both.
	AGF._errors = errorLog;
})(
	typeof window !== "undefined"
		? (window.AGF = window.AGF || {})
		: (globalThis.AGF = globalThis.AGF || {}),
);
